	('ab799ce7-dfa0-438b-8e2c-711b5a36c58a', 'CREATED', 'NFR_DEFINITION_VERSION', '7854d09b-c2b7-4203-8dc6-a74ab46107e1', 'seed-user-admin-clara', NULL, NULL, '{"after": {"slcPhase": "BUILD", "itProcess": "MANAGE_DELIVERY", "objective": "The digital solution must have user friendly, clear and accessible mechanisms for human operators to override the AI solution''s decisions, recommendations, or operations when necessary.", "ownerTeam": "DIGITAL_DATA", "statement": "I want to ensure that oversight measures are designed into the AI digital solution to enable human intervention when needed.", "triggerRule": {"groups": [{"conditions": [{"values": ["AI_HIGH"], "operator": "IN", "outcomeKey": "AI_RISK_CLASSIFICATION"}]}]}, "definitionId": "080a936d-d43f-45c7-8ac5-6c65a04fb0e2", "reviewerTeam": null, "sourceOfTruth": "", "versionNumber": 1, "versionReason": "INITIAL_IMPORT", "attestationType": "SELF_ATTESTATION", "createdByUserId": "seed-user-admin-clara", "targetedEvidence": "", "applicabilityType": "OUTCOME_TRIGGERED", "catalogVersionKey": "RISK_PROFILE_V1", "attestationGuidance": "", "autoAttestationRule": null, "revalidationIntervalMonths": null}, "before": null}', '2026-08-10 00:00:00', 'USER'),
