BEGIN;
DO $dpr_dev_seed$
BEGIN
  IF EXISTS (SELECT 1 FROM "user")
     OR EXISTS (SELECT 1 FROM region)
     OR EXISTS (SELECT 1 FROM control_definition)
     OR EXISTS (SELECT 1 FROM nfr_definition)
     OR EXISTS (SELECT 1 FROM audit_event)
  THEN
    RAISE EXCEPTION 'DEV seed target is not empty';
  END IF;
END
$dpr_dev_seed$;

